inSequence.script:
var xmlResponse = mc.getPayloadXML();
                var registros = xmlResponse..Registro;
                var lista = [];

                for (var i = 0; i < registros.length(); i++) {
                    var reg = registros[i];
                    lista.push({
                        "id": reg.Id.toString(),
                        "placaVeiculo": reg.PlacaVeiculo.toString(),
                        "quilometragem": parseFloat(reg.Quilometrajem.toString()),
                        "statusFrota": reg.StatusFrota.toString(),
                        "ultimaManutencao": reg.UltimaManutencao.toString()
                    });
                }

                var jsonResponse = {
                    "relatorioConsolidado": {
                        "header": {
                            "empresa": mc.getProperty("empresa"),
                            "totalRegistros": parseInt(mc.getProperty("totalRegistros")),
                            "dataGeracao": mc.getProperty("dataGeracao")
                        },
                        "listaRegistros": lista
                    }
                };

                mc.setPayloadJSON(jsonResponse);

payloadFactory.format:
{
    "erro": "Falha na comunicacao com o serviço backend de relatorios.",
    "codigo": "$1"
}
